    """
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]

    # Dividers are long runs of 2s; ring markers may interrupt them.
    sep_rows = {r for r in range(h)
                if sum(src[r][c] == 2 for c in range(w)) * 2 >= w}
    sep_cols = {c for c in range(w)
                if sum(src[r][c] == 2 for r in range(h)) * 2 >= h}

    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
